"""Writes docs/RAW_INVENTORY.md: what is in data/raw (counts, bytes, date span, content hash per source folder). No content. Raw data is git-ignored and re-pullable
except where the source no longer serves old posts, so the hashes let a rebuild be matched to the inputs that made it.   usage: python3 -I scripts/raw_inventory.py"""
import os, hashlib, glob, datetime
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."); raw = os.path.join(root, "data/raw")
out = ["# Raw data inventory", "", f"Generated by `python3 -I scripts/raw_inventory.py` on {datetime.date.today().isoformat()}. Counts, sizes and hashes only; the files are git-ignored. How each source is pulled: DATA_SOURCES.md.", "",
       "| Folder | Files | MB | Newest file date | Content hash (first 16) |", "|---|---|---|---|---|"]
for d in sorted(os.listdir(raw)):
    fs = sorted(p for p in glob.glob(os.path.join(raw, d, "**", "*"), recursive=True) if os.path.isfile(p))
    h = hashlib.sha256()
    for p in fs: h.update(open(p, "rb").read())
    new = max((os.path.getmtime(p) for p in fs), default=0)
    out.append(f"| {d} | {len(fs)} | {sum(os.path.getsize(p) for p in fs)/1e6:.1f} | {datetime.date.fromtimestamp(new).isoformat() if fs else ''} | {h.hexdigest()[:16]} |")
out += ["", "Pull dates are file modification dates, which can change on copy; the hash is the stable fingerprint.", "A private archive of the raw folder is kept outside git (see the owner's handoff notes)."]
open(os.path.join(root, "docs/RAW_INVENTORY.md"), "w").write("\n".join(out) + "\n"); print("\n".join(out[4:-3]))
